verifier_test:
# Проверяем, что пароль заблокирован
passwd -S contractor | grep "LOCKED" || { echo "Password for contractor is not locked"; exit 1; }

# Проверяем, что дата истечения срока действия учётной записи установлена на 1970-01-02
chage -l contractor | grep "Account expires" | grep "1970-01-02" || { echo "Expiry date for contractor is not set to 1970-01-02"; exit 1; }

# Проверяем, что оболочка для contractor установлена на /usr/sbin/nologin
grep -q "^contractor:x:.*:.*:.*:/home/contractor:/usr/sbin/nologin" /etc/passwd || { echo "Shell for contractor is not set to /usr/sbin/nologin"; exit 1; }

# Проверяем, что домашняя директория для contractor не была удалена
test -d /home/contractor || { echo "Home directory for contractor was removed"; exit 1; }

# Проверяем, что файл authorized_keys для contractor не был удален
test -f /home/contractor/.ssh/authorized_keys || { echo "authorized_keys file for contractor was removed"; exit 1; }

# Если все проверки пройдены, завершаем с кодом 0
exit 0

